#include <atomic>
#include <new>
#include <thread>
int main() {
    auto* value = static_cast<volatile int*>(::operator new(sizeof(int)));
    *value = 0;
    std::atomic<bool> start{false};
    const auto race = [&] {
        while (!start.load()) std::this_thread::yield();
        for (int i = 0; i < 10000; ++i) *value = *value + 1;
    };
    std::thread a(race), b(race);
    start.store(true);
    a.join(); b.join();
    ::operator delete(const_cast<int*>(value));
}
